$t['Automatic setup creates the webhook for this site URL only, or adds the missing events to it and keeps any other events. It saves the Webhook ID used to verify signatures. It never deletes webhooks, never touches other URLs and never changes the app permissions.'] = 'Η αυτόματη ρύθμιση δημιουργεί το webhook μόνο για το URL αυτού του ιστότοπου ή προσθέτει σε αυτό τα συμβάντα που λείπουν και διατηρεί τυχόν άλλα συμβάντα. Αποθηκεύει το Webhook ID που χρησιμοποιείται για την επαλήθευση των υπογραφών. Δεν διαγράφει ποτέ webhooks, δεν αγγίζει ποτέ άλλα URL και δεν αλλάζει ποτέ τα δικαιώματα της εφαρμογής.';
$t['Automatic setup needs Webhook Endpoints: Write. It creates the webhook and securely saves its new signing secret, or enables the existing endpoint and adds missing events. It preserves existing events and does not replace endpoints or change API key permissions.'] = 'Η αυτόματη ρύθμιση απαιτεί το δικαίωμα Webhook Endpoints: Write. Δημιουργεί το webhook και αποθηκεύει με ασφάλεια το νέο μυστικό κλειδί υπογραφής του ή ενεργοποιεί το υπάρχον endpoint και προσθέτει τα συμβάντα που λείπουν. Διατηρεί τα υπάρχοντα συμβάντα και δεν αντικαθιστά endpoints ούτε αλλάζει τα δικαιώματα του κλειδιού API.';
