$t['Final test: complete a sandbox purchase, confirm an HTTP 200 delivery in Stripe, then check the wallet or rental, subscription access and video playback. Also test a declined card and 3D Secure. Never retry a charged payment just because access is still pending.'] = 'Τελικός έλεγχος: ολοκληρώστε μια αγορά sandbox, επιβεβαιώστε μια παράδοση HTTP 200 στο Stripe και, στη συνέχεια, ελέγξτε το πορτοφόλι ή την ενοικίαση, την πρόσβαση συνδρομής και την αναπαραγωγή βίντεο. Δοκιμάστε επίσης μια κάρτα που απορρίπτεται και το 3D Secure. Μην επαναλαμβάνετε ποτέ μια χρεωμένη πληρωμή μόνο επειδή η πρόσβαση εκκρεμεί ακόμα.';
