$t['The commit identifies the Git revision checked out on this server; local file edits are not included. A Git tag is shown when one points directly to that commit.'] = 'Το commit προσδιορίζει την αναθεώρηση Git που είναι ενεργή σε αυτόν τον διακομιστή· οι τοπικές αλλαγές αρχείων δεν περιλαμβάνονται. Εμφανίζεται ένα tag Git όταν αυτό δείχνει απευθείας σε εκείνο το commit.';
$t['The Companion Chat service is not available right now. Ask your site administrator to check the AI plugin connection.'] = 'Η υπηρεσία Companion Chat δεν είναι διαθέσιμη αυτή τη στιγμή. Ζητήστε από τον διαχειριστή του ιστότοπου να ελέγξει τη σύνδεση του πρόσθετου AI.';
$t['The connection could not be renewed. Please reconnect your account.'] = 'Δεν ήταν δυνατή η ανανέωση της σύνδεσης. Συνδέστε ξανά τον λογαριασμό σας.';
$t['The connection expired and could not be renewed. Please reconnect your account.'] = 'Η σύνδεση έληξε και δεν ήταν δυνατή η ανανέωσή της. Συνδέστε ξανά τον λογαριασμό σας.';
$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = 'Η σύνδεση με τον προορισμό διακόπηκε κατά τη μετάδοση. Ίσως πρόκειται για προσωρινό πρόβλημα δικτύου· το FFMPEG θα προσπαθήσει να επανασυνδεθεί.';
$t['The connection to YouTube was interrupted. The upload was paused and can be resumed.'] = 'Η σύνδεση με το YouTube διακόπηκε. Η μεταφόρτωση τέθηκε σε παύση και μπορεί να συνεχιστεί.';
$t['The connection was interrupted. Check your account before retrying this subscription.'] = 'Η σύνδεση διακόπηκε. Ελέγξτε τον λογαριασμό σας πριν επαναλάβετε αυτή τη συνδρομή.';
$t['The connection was renewed.'] = 'Η σύνδεση ανανεώθηκε.';
$t['The connection window was closed before the authorization finished. No account was connected.'] = 'Το παράθυρο σύνδεσης έκλεισε πριν ολοκληρωθεί η εξουσιοδότηση. Δεν συνδέθηκε κανένας λογαριασμός.';
$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = 'Τα αρχεία που μετατράπηκαν διατηρήθηκαν. Επικοινωνήστε με τον διαχειριστή του ιστότοπου για να επαναλάβει τη μεταφορά· δεν χρειάζεται να ανεβάσετε ξανά το βίντεο.';
$t['The converted video could not be sent back to this site.'] = 'Δεν ήταν δυνατή η αποστολή του βίντεο που μετατράπηκε πίσω σε αυτόν τον ιστότοπο.';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = 'Οι πελάτες της επιλεγμένης κάρτας. Αναζητήστε, ταξινομήστε, αντιγράψτε τα e-mail ή εξαγάγετε τα πάντα σε υπολογιστικό φύλλο.';
$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'Συμπληρώθηκε το ημερήσιο όριο μεταφορτώσεων YouTube αυτού του ιστότοπου. Οι μεταφορτώσεις θα είναι ξανά διαθέσιμες μετά τα μεσάνυχτα ώρας Ειρηνικού. Δοκιμάστε ξανά αργότερα.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'Η έκδοση της βάσης δεδομένων αλλάζει μόνο όταν εφαρμόζεται μια μετάβαση (migration) της βάσης δεδομένων. Δεν αναμένεται να ταιριάζει με το tag έκδοσης ή το commit.';
$t['The default'] = 'Η προεπιλογή';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = 'Ο διακομιστής RTMP προορισμού απέρριψε τη σύνδεση. Ελέγξτε το URL μετάδοσης και βεβαιωθείτε ότι ο διακομιστής είναι σε λειτουργία.';
$t['The destination server requires authentication. Check the stream key.'] = 'Ο διακομιστής προορισμού απαιτεί έλεγχο ταυτότητας. Ελέγξτε το κλειδί μετάδοσης.';
$t['The destination server returned 403. The stream key may be invalid or expired.'] = 'Ο διακομιστής προορισμού επέστρεψε 403. Το κλειδί μετάδοσης ίσως είναι άκυρο ή έχει λήξει.';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = 'Το βίντεο προορισμού αφαιρέθηκε ή αυτός ο λογαριασμός δεν μπορεί να το επεξεργαστεί. Ελέγξτε το βίντεο και την πρόσβαση του λογαριασμού στον ιστότοπο.';
$t['The download is controlled by the system, there is nothing to check on the user'] = 'The download is controlled by the system, there is nothing to check on the user';
$t['The download permission is site wide, so there is nothing to check on the video'] = 'Η άδεια λήψης ισχύει για όλο τον ιστότοπο, επομένως δεν υπάρχει τίποτα να ελεγχθεί στο βίντεο';
$t['The download permission is site wide, so there is nothing to check onthe video'] = 'The download permission is site wide, so there is nothing to check onthe video';
$t['The email is invalid'] = 'The email is invalid';
$t['The encoder could not download the original file.'] = 'Ο κωδικοποιητής δεν μπόρεσε να κατεβάσει το αρχικό αρχείο.';
$t['The encoder could not find this video on the site.'] = 'Ο κωδικοποιητής δεν βρήκε αυτό το βίντεο στον ιστότοπο.';
$t['The encoder did not confirm that the video was added to the queue. Please retry.'] = 'Ο κωδικοποιητής δεν επιβεβαίωσε ότι το βίντεο προστέθηκε στην ουρά. Δοκιμάστε ξανά.';
$t['The encoder is running out of disk space'] = 'Ο κωδικοποιητής εξαντλεί τον χώρο στον δίσκο';
$t['The encoder reported an unexpected error.'] = 'Ο κωδικοποιητής ανέφερε ένα απροσδόκητο σφάλμα.';
$t['The encoding process stopped unexpectedly, and the automatic retries also failed.'] = 'Η διαδικασία κωδικοποίησης σταμάτησε απροσδόκητα και οι αυτόματες επαναλήψεις απέτυχαν επίσης.';
$t['The encoding queue is stalled'] = 'Η ουρά κωδικοποίησης έχει κολλήσει';
$t['The event purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'Η αγορά της εκδήλωσης δεν ολοκληρώθηκε. Η πληρωμή από το πορτοφόλι σας δεν χρεώθηκε. Ελέγξτε το υπόλοιπό σας πριν δοκιμάσετε ξανά.';
$t['The file could not be converted. It may be damaged or use a format the encoder does not support.'] = 'Δεν ήταν δυνατή η μετατροπή του αρχείου. Μπορεί να είναι κατεστραμμένο ή να χρησιμοποιεί μορφή που δεν υποστηρίζει ο κωδικοποιητής.';
$t['The file must be an .vtt file!'] = 'The file must be an .vtt file!';
$t['The file must be an .vtt or .srt file!'] = 'Το αρχείο πρέπει να είναι αρχείο .vtt ή .srt!';
$t['The final charge uses the duration measured during processing. A connected Marketplace wallet is required.'] = 'Η τελική χρέωση χρησιμοποιεί τη διάρκεια που μετρήθηκε κατά την επεξεργασία. Απαιτείται συνδεδεμένο πορτοφόλι Marketplace.';
$t['The following movie contains materials that are not suitable for children 17 and under.'] = 'Η παρακάτω ταινία περιέχει υλικό ακατάλληλο για παιδιά ηλικίας 17 ετών και κάτω.';
$t['The following movie contains materials that may not be suitable for children 17 and under.'] = 'Η παρακάτω ταινία περιέχει υλικό που ενδέχεται να είναι ακατάλληλο για παιδιά ηλικίας 17 ετών και κάτω.';
$t['The form to signup will not exists'] = 'The form to signup will not exists';
$t['The gift code has been canceled. If this is unexpected, please contact our support team.'] = 'Ο κωδικός δώρου ακυρώθηκε. Αν αυτό είναι απροσδόκητο, επικοινωνήστε με την ομάδα υποστήριξης.';
$t['The gift code is currently inactive. Please check back later or contact support.'] = 'Ο κωδικός δώρου είναι προς το παρόν ανενεργός. Δοκιμάστε ξανά αργότερα ή επικοινωνήστε με την υποστήριξη.';
$t['The information above corresponds to our official records and confirms the authenticity of this certificate.'] = 'Τα παραπάνω στοιχεία αντιστοιχούν στα επίσημα αρχεία μας και επιβεβαιώνουν τη γνησιότητα αυτού του πιστοποιητικού.';
$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = 'Η ροή εισόδου περιέχει μη έγκυρα δεδομένα. Η πηγή HLS μπορεί να μην είναι ακόμη έτοιμη ή η ροή διακόπηκε.';
$t['The installed PHP package lists both fixes, but this web process still runs the copy loaded before the update. Restart Apache or PHP-FPM.'] = 'Το εγκατεστημένο πακέτο PHP περιλαμβάνει και τις δύο διορθώσεις, αλλά αυτή η διεργασία web εξακολουθεί να εκτελεί το αντίγραφο που φορτώθηκε πριν από την ενημέρωση. Επανεκκινήστε τον Apache ή το PHP-FPM.';
$t['Their last plans add up to %s'] = 'Τα τελευταία προγράμματά τους ανέρχονται σε %s';
$t['The list was limited to the first %s results.'] = 'Η λίστα περιορίστηκε στα πρώτα %s αποτελέσματα.';
$t['The live service could not complete the request. Please try again.'] = 'Η υπηρεσία ζωντανής μετάδοσης δεν μπόρεσε να ολοκληρώσει το αίτημα. Δοκιμάστε ξανά.';
$t['The live that was still being sent to this destination was stopped.'] = 'Η ζωντανή μετάδοση που εξακολουθούσε να αποστέλλεται σε αυτόν τον προορισμό σταμάτησε.';
