$t['The purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'Η αγορά δεν ολοκληρώθηκε. Η πληρωμή από το πορτοφόλι σας δεν χρεώθηκε. Ελέγξτε το υπόλοιπό σας πριν δοκιμάσετε ξανά.';
$t['There\'s an unknown status associated with this gift code. Please contact support for assistance.'] = 'Υπάρχει άγνωστη κατάσταση για αυτόν τον κωδικό δώρου. Επικοινωνήστε με την υποστήριξη για βοήθεια.';
$t['There, you can set'] = 'There, you can set';
