$t['There is no Pay Per View plan yet. Create one in the Pay-Per-View plugin, PPV Plans tab.'] = 'Δεν υπάρχει ακόμη πρόγραμμα Pay Per View. Δημιουργήστε ένα στο plugin Pay-Per-View, καρτέλα PPV Plans.';
$t['There is no plan that can hold videos yet. Create one in the PPV Plans tab, then come back here.'] = 'Δεν υπάρχει ακόμη πρόγραμμα που να μπορεί να περιέχει βίντεο. Δημιουργήστε ένα στην καρτέλα PPV Plans και μετά επιστρέψτε εδώ.';
$t['There is no streaming now'] = 'There is no streaming now';
$t['The release number and the AVideo database version are independent. Code update status is determined by commit history.'] = 'Ο αριθμός έκδοσης και η έκδοση της βάσης δεδομένων του AVideo είναι ανεξάρτητα. Η κατάσταση ενημέρωσης του κώδικα καθορίζεται από το ιστορικό commit.';
$t['The request to the social network failed. Please try again later.'] = 'Το αίτημα προς το κοινωνικό δίκτυο απέτυχε. Δοκιμάστε ξανά αργότερα.';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = 'Ο διακομιστής restreamer δεν μπορεί να φτάσει τον προορισμό. Ελέγξτε τη συνδεσιμότητα δικτύου.';
$t['The same alert is repeated at most every %s while the problem continues.'] = 'Η ίδια ειδοποίηση επαναλαμβάνεται το πολύ κάθε %s όσο συνεχίζεται το πρόβλημα.';
$t['The same alert is repeated at most every few hours while the problem continues.'] = 'Η ίδια ειδοποίηση επαναλαμβάνεται το πολύ κάθε λίγες ώρες όσο συνεχίζεται το πρόβλημα.';
$t['The selected camera or microphone is not available. Please choose another device.'] = 'Η επιλεγμένη κάμερα ή το μικρόφωνο δεν είναι διαθέσιμα. Επιλέξτε άλλη συσκευή.';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'Η επιλεγμένη θέση επισημαίνεται σε πραγματική σελίδα. Η προεπισκόπηση για κινητά αλλάζει μόνο τις θέσεις των διαφημίσεων· η υπόλοιπη σελίδα χρησιμοποιεί τη συσκευή του προγράμματος περιήγησής σας.';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'Η επιλεγμένη θέση επισημαίνεται σε μια πραγματική σελίδα του ιστότοπού σας και ακολουθεί τη θέση που επιλέγετε παρακάτω. Η προεπισκόπηση για κινητά αλλάζει μόνο τις θέσεις των διαφημίσεων· η υπόλοιπη σελίδα χρησιμοποιεί τη συσκευή του προγράμματος περιήγησής σας.';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'Ο ιστότοπος είναι προσωρινά εκτός λειτουργίας λόγω προβλήματος στη βάση δεδομένων. Εργαζόμαστε για να επιλύσουμε το πρόβλημα το συντομότερο δυνατό.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'Ο ιστότοπος δεν είναι προσωρινά διαθέσιμος επειδή ο δίσκος του διακομιστή είναι γεμάτος. Εργαζόμαστε για το ζήτημα και θα επιστρέψουμε σύντομα.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'Ο ιστότοπος βρίσκεται υπό συντήρηση καθώς ο δίσκος του διακομιστή πλησιάζει τη μέγιστη χωρητικότητα. Αντιμετωπίζουμε το ζήτημα και θα επιστρέψουμε σύντομα.';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'Ο ιστότοπος αρνήθηκε την πρόσβαση. Ανανεώστε την πρόσβαση του λογαριασμού του κωδικοποιητή και ελέγξτε τα δικαιώματα μεταφόρτωσής του.';
$t['The site will display only a login form to un authenticated users'] = 'The site will display only a login form to un authenticated users';
$t['The source stream ended. If the live was stopped intentionally this is normal.'] = 'Η ροή πηγής τερματίστηκε. Αν η ζωντανή μετάδοση διακόπηκε σκόπιμα, αυτό είναι φυσιολογικό.';
$t['The split is on: desktop visitors do not see this banner now, they see the left and right halves.'] = 'Ο διαχωρισμός είναι ενεργός: οι επισκέπτες από υπολογιστή δεν βλέπουν τώρα αυτό το banner, βλέπουν το αριστερό και το δεξί μισό.';
$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = 'Η ροή έχει ασυνέχειες χρονοσφραγίδων. Αυτό μπορεί να προκαλέσει buffering ή προβλήματα αναπαραγωγής στην πλατφόρμα προορισμού.';
$t['The subtitle has not been copied to the player yet.'] = 'Ο υπότιτλος δεν έχει αντιγραφεί ακόμη στο πρόγραμμα αναπαραγωγής.';
