$t['Your webhook endpoint should respond with HTTP 200 status code for successful processing. The request timeout is 1 second, so ensure your endpoint responds quickly.'] = 'Το endpoint του webhook σας πρέπει να απαντά με κωδικό κατάστασης HTTP 200 για επιτυχή επεξεργασία. Το χρονικό όριο του αιτήματος είναι 1 δευτερόλεπτο, οπότε βεβαιωθείτε ότι το endpoint απαντά γρήγορα.';
$t['Your Webhook Secret Key:'] = 'Το μυστικό κλειδί του Webhook σας:';
$t['Your YouTube authorization expired or was revoked. Reconnect your YouTube account and try again.'] = 'Η εξουσιοδότηση YouTube έληξε ή ανακλήθηκε. Συνδέστε ξανά τον λογαριασμό σας YouTube και δοκιμάστε ξανά.';
$t['Your YouTube channel reached its daily upload limit. Please try again in 24 hours.'] = 'Το κανάλι σας στο YouTube έφτασε το ημερήσιο όριο μεταφορτώσεων. Δοκιμάστε ξανά σε 24 ώρες.';
