$t['YouTube: Google only lists channels you own or manage as a Brand Account. If your channel is not listed, fill in its stream URL and stream key by hand in the form.'] = 'YouTube: Η Google εμφανίζει μόνο κανάλια που σας ανήκουν ή που διαχειρίζεστε ως Brand Account. Αν το κανάλι σας δεν εμφανίζεται, συμπληρώστε χειροκίνητα το URL ροής και το κλειδί ροής στη φόρμα.';
$t['YouTube accepts up to 100 characters.'] = 'Το YouTube δέχεται έως 100 χαρακτήρες.';
$t['YouTube accepts up to 5000 characters. HTML is removed.'] = 'Το YouTube δέχεται έως 5000 χαρακτήρες. Η HTML αφαιρείται.';
$t['YouTube and other supported video links download through your own connection, which can help when a provider blocks the Encoder server.'] = 'Οι σύνδεσμοι YouTube και άλλων υποστηριζόμενων βίντεο κατεβαίνουν μέσω της δικής σας σύνδεσης, κάτι που βοηθά όταν ένας πάροχος μπλοκάρει τον διακομιστή του Encoder.';
$t['YouTube category'] = 'Κατηγορία YouTube';
$t['YouTube could not process the uploaded file. Check that the video plays correctly on this site and publish it again.'] = 'Το YouTube δεν μπόρεσε να επεξεργαστεί το αρχείο που μεταφορτώθηκε. Ελέγξτε ότι το βίντεο αναπαράγεται σωστά σε αυτόν τον ιστότοπο και δημοσιεύστε το ξανά.';
$t['YouTube Data API'] = 'YouTube Data API';
$t['YouTube Data API Overview'] = 'YouTube Data API Overview';
$t['YouTube did not accept the description. Edit the description and publish again.'] = 'Το YouTube δεν αποδέχτηκε την περιγραφή. Επεξεργαστείτε την περιγραφή και δημοσιεύστε ξανά.';
$t['YouTube did not accept the selected category. Choose another category and publish again.'] = 'Το YouTube δεν αποδέχτηκε την επιλεγμένη κατηγορία. Επιλέξτε άλλη κατηγορία και δημοσιεύστε ξανά.';
$t['YouTube did not accept the selected privacy setting. Choose another one and publish again.'] = 'Το YouTube δεν αποδέχτηκε την επιλεγμένη ρύθμιση απορρήτου. Επιλέξτε άλλη και δημοσιεύστε ξανά.';
$t['YouTube did not accept the tags. Edit the tags and publish again.'] = 'Το YouTube δεν αποδέχτηκε τις ετικέτες. Επεξεργαστείτε τις ετικέτες και δημοσιεύστε ξανά.';
$t['YouTube did not accept the title. Edit the title and publish again.'] = 'Το YouTube δεν αποδέχτηκε τον τίτλο. Επεξεργαστείτε τον τίτλο και δημοσιεύστε ξανά.';
$t['YouTube did not accept the video details. Check the title, description and tags, then publish again.'] = 'Το YouTube δεν αποδέχτηκε τα στοιχεία του βίντεο. Ελέγξτε τον τίτλο, την περιγραφή και τις ετικέτες και δημοσιεύστε ξανά.';
$t['YouTube did not allow this upload. Reconnect your YouTube account and allow this website to manage your YouTube videos.'] = 'Το YouTube δεν επέτρεψε αυτήν τη μεταφόρτωση. Συνδέστε ξανά τον λογαριασμό σας YouTube και επιτρέψτε σε αυτόν τον ιστότοπο να διαχειρίζεται τα βίντεό σας στο YouTube.';
$t['YouTube is receiving too many requests right now. Please wait a few minutes and try again.'] = 'Το YouTube λαμβάνει πάρα πολλά αιτήματα αυτήν τη στιγμή. Περιμένετε λίγα λεπτά και δοκιμάστε ξανά.';
$t['YouTube rejected the video because it does not follow the YouTube policies.'] = 'Το YouTube απέρριψε το βίντεο επειδή δεν συμμορφώνεται με τις πολιτικές του YouTube.';
$t['YouTube rejected the video because it is a duplicate of a video already on your channel.'] = 'Το YouTube απέρριψε το βίντεο επειδή είναι διπλότυπο ενός βίντεο που υπάρχει ήδη στο κανάλι σας.';
$t['YouTube rejected the video because it is longer than your channel allows. Verify your YouTube account to upload longer videos.'] = 'Το YouTube απέρριψε το βίντεο επειδή είναι μεγαλύτερο από όσο επιτρέπει το κανάλι σας. Επαληθεύστε τον λογαριασμό σας YouTube για να μεταφορτώνετε μεγαλύτερα βίντεο.';
$t['YouTube rejected the video because of a copyright claim.'] = 'Το YouTube απέρριψε το βίντεο λόγω αξίωσης πνευματικών δικαιωμάτων.';
$t['YouTube returned an unexpected error. Please try again later. If the problem continues, contact the site administrator.'] = 'Το YouTube επέστρεψε ένα μη αναμενόμενο σφάλμα. Δοκιμάστε ξανά αργότερα. Αν το πρόβλημα συνεχιστεί, επικοινωνήστε με τον διαχειριστή του ιστότοπου.';
